def transform(grid):
    """Copy the colored pattern around one 5 marker to the other marker."""
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 5]
    if len(markers) != 2:
        return out

    def nearby_nonzero(r, c):
        return sum(
            grid[rr][cc] != 0
            for rr in range(max(0, r - 2), min(len(grid), r + 3))
            for cc in range(max(0, c - 3), min(len(grid[0]), c + 4))
            if (rr, cc) != (r, c)
        )

    source = max(markers, key=lambda p: nearby_nonzero(*p))
    target = markers[0] if markers[1] == source else markers[1]
    dr, dc = target[0] - source[0], target[1] - source[1]
    out[target[0]][target[1]] = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value and (r, c) != source:
                rr, cc = r + dr, c + dc
                if 0 <= rr < len(grid) and 0 <= cc < len(row):
                    out[rr][cc] = value
    return out
